import { useState, useEffect } from "react";

function useFetchBatters<T>(): {
  data: T[];
  error: null | string;
  isLoading: boolean;
  refetch: (
    clearData: boolean,
    getTomorrow: boolean,
    signal?: AbortSignal
  ) => void;
  cancel: () => void; // ✅ expose cancel
} {
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<null | string>(null);
  const [data, setData] = useState<T[]>([]);

  const fetchTopBatters = async (
    clearData: boolean = false,
    getTomorrow: boolean = false,
    signal?: AbortSignal
  ) => {
    setIsLoading(true);

    const controller = signal ? null : new AbortController();
    const effectiveSignal = signal || controller?.signal;

    try {
      const response = await fetch(
        `http://localhost:3001/api/scraper?clear=${clearData}&tomorrow=${getTomorrow}`,
        { signal: effectiveSignal }
      );
      if (!response.ok) {
        const text = await response.text();
        throw new Error(`Server error: ${response.status} - ${text}`);
      }

      const data: T[] = await response.json();
      setData(data);
    } catch (err: any) {
      if (err.name === "AbortError") {
        console.log("Fetch aborted");
      } else {
        console.log("Error fetching top batters:" + err);
        setError("Error fetching top batters");
      }
    } finally {
      setIsLoading(false); // ✅ always reset loading
    }
  };

  const cancel = () => {
    setIsLoading(false); // ✅ externally callable cancel
  };

  useEffect(() => {
    const controller = new AbortController();
    fetchTopBatters(false, false, controller.signal);

    return () => {
      controller.abort();
    };
  }, []);

  return { data, error, isLoading, refetch: fetchTopBatters, cancel };
}

export default useFetchBatters;
